/**
 * Golden bytes. These constants were captured from the code as it stood at commit c3d1abe
 * (EVM-only). Any refactor that changes a single byte of what goes to the wallet, or a wei of
 * msg.value, fails here — that is the point. Do not "update the expected value" without a
 * deliberate, explained decision.
 */
import { describe, expect, it } from 'vitest'
import { encodeFunctionData } from 'viem'
import { erc20Abi } from '@/core/abi'
import { assembleSendArgs, computeValue, encodeSendCalldata } from '@/core/plan'
import { HYPER_FEE_STEP, OTHER, TREAD_ADAPTER, treadPlan } from './fixtures'

const SEND_DEFAULT =
  ''

const SEND_CUSTOM =
  ''

const APPROVE_EXACT =
  '0x095ea7b3000000000000000000000000e68ad53cf0d5e49cf83fbc003672f6d0ebcae311000000000000000000000000000000000000000000000001130ec8fd383e0000'

describe('golden: send calldata', () => {
  it('19.82 TREAD, HyperEVM → Ethereum, recipient = wallet, no options', () => {
    expect(encodeSendCalldata(assembleSendArgs(treadPlan()))).toBe(SEND_DEFAULT)
  })
  it('0.000001 TREAD to a custom recipient with enforced-style extraOptions', () => {
    const plan = treadPlan({ recipient: OTHER, extraOptions: '0x0003010011010000000000000000000000000000ea60' }, '0.000001')
    expect(encodeSendCalldata(assembleSendArgs(plan))).toBe(SEND_CUSTOM)
  })
  it('the wallet receives exactly value === fee.nativeFee from the same plan', () => {
    const plan = treadPlan()
    const [, fee] = assembleSendArgs(plan)
    expect(fee.nativeFee).toBe(plan.value)
    expect(plan.value).toBe(30_000000000000000n)
  })
})

describe('golden: approve calldata', () => {
  it('approve(adapter, exactly 19.82 TREAD)', () => {
    expect(encodeFunctionData({ abi: erc20Abi, functionName: 'approve', args: [TREAD_ADAPTER, 19_820000000000000000n] })).toBe(APPROVE_EXACT)
  })
})

describe('golden: computeValue rounding', () => {
  it.each<[bigint, number, bigint, bigint]>([
    [20_800000000000000n, 4000, HYPER_FEE_STEP, 30_000000000000000n], // the §8 example: 0.0208 → 0.03 HYPE
    [1n, 4000, HYPER_FEE_STEP, 10_000000000000000n], // one wei still rounds up to a whole step
    [0n, 4000, HYPER_FEE_STEP, 0n],
    [123456789012345n, 0, 10n ** 14n, 200000000000000n],
    [123456789012345n, 4000, 10n ** 13n, 180000000000000n],
    [999_999_999_999_999_999n, 4000, 10n ** 16n, 1_400000000000000000n],
    [12345n, 0, 1n, 12345n],
  ])('computeValue(%s, %s bps, step %s) = %s', (fee, bps, step, expected) => {
    expect(computeValue(fee, bps, step)).toBe(expected)
  })
})
